#[derive(serde::Deserialize)]
#[allow(dead_code)]
pub(crate) struct ChatCompletionResponse {
    #[serde(default)]
    pub(crate) choices: Vec<ChatChoice>,
    #[serde(default)]
    pub(crate) usage: Option<ChatUsage>,
}

#[derive(serde::Deserialize)]
#[allow(dead_code)]
pub(crate) struct ChatChoice {
